sql_query:
SELECT DISTINCT VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT, ALS_1, ALS_2, ALS_3, ALS_4, ALS_5 
FROM varInfo_synthetic 
WHERE HighImpact = 1 AND (ALS_1 = 2 OR ALS_2 = 2 OR ALS_3 = 2 OR ALS_4 = 2 OR ALS_5 = 2);

SELECT AVG(AF) AS Avg_AF 
FROM varInfo_synthetic 
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE HighImpact = 'YES' AND ALS_1 = 1;

SELECT VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT, ALS_1, ALS_2, ALS_3, ALS_4, ALS_5, Control_1, Control_2, Control_3, Control_4, Control_5
FROM varInfo_synthetic
WHERE HighImpact = 1 OR ModerateImpact = 1;

SELECT VAR_id 
FROM varInfo_synthetic 
WHERE Synonymous = '1' AND HighImpact = '1';

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND HighImpact + ModerateImpact > 0 AND Control_1 = 'female';

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND ModerateImpact > 0 OR HighImpact > 0 AND FILTER LIKE '%somatic%';

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND HighImpact > 0 AND Synonymous = 0 AND ModerateImpact = 0 AND ALS_5 = 1;
